void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;

    // Circle
    vec2 circleCenter = vec2(0.3, 0.5);
    float circleRadius = 0.2;
    float circleDist = length(uv - circleCenter);

    // Rectangle
    vec2 rectBottomLeft = vec2(0.5, 0.4);
    vec2 rectTopRight = vec2(0.7, 0.6);
    bool inRectangle = uv.x > rectBottomLeft.x && uv.x < rectTopRight.x && uv.y > rectBottomLeft.y && uv.y < rectTopRight.y;

    if (circleDist < circleRadius) {
        fragColor = vec4(1.0, 0.5, 0.2, 1.0); // Circle color
    } else if (inRectangle) {
        fragColor = vec4(0.2, 0.8, 0.4, 1.0); // Rectangle color
    } else {
        fragColor = vec4(0.0, 0.0, 0.0, 1.0); // Background color
    }
}
